CREATE OR REPLACE FUNCTION gym20.convert_registration_request(p_request_id uuid)
 RETURNS TABLE(student_id uuid, enrollment_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_owner_id uuid;
  v_request gym20.public_registration_requests%rowtype;
  v_student_id uuid;
  v_style text;
  v_course_name text;
  v_course_id uuid;
  v_count integer := 0;
begin
  v_owner_id := (select auth.uid());
  if v_owner_id is null or not (select gym20.is_active_owner()) then
    raise exception 'اجازه انجام این عملیات را ندارید.' using errcode = '42501';
  end if;

  select *
    into v_request
    from gym20.public_registration_requests
   where id = p_request_id
   for update;

  if not found then
    raise exception 'درخواست ثبت‌نام پیدا نشد.';
  end if;

  if v_request.converted_student_id is not null or v_request.status = 'converted' then
    raise exception 'این درخواست قبلاً به هنرجو تبدیل شده است.';
  end if;

  if v_request.status = 'rejected' then
    raise exception 'ابتدا وضعیت درخواست ردشده را اصلاح کنید.';
  end if;

  if coalesce(cardinality(v_request.selected_styles),0) = 0 then
    raise exception 'درخواست هیچ سبک ورزشی معتبری ندارد.';
  end if;

  insert into gym20.students(full_name, phone, birth_date, notes, is_active)
  values (
    v_request.full_name,
    v_request.phone,
    v_request.birth_date,
    v_request.notes,
    true
  )
  returning id into v_student_id;

  for v_style in
    select distinct btrim(s.style_name)
      from unnest(v_request.selected_styles) as s(style_name)
     order by 1
  loop
    v_course_name := case
      when v_style ilike '%بریک%دنس%' then 'بریک‌دنس'
      when v_style ilike '%بوکس%' then 'بوکس'
      when v_style ilike '%پارکور%' then 'پارکور'
      when v_style ilike '%کلیستنیکس%' or v_style ilike '%کالیستنیکس%' then 'کلیستنیکس'
      when v_style ilike '%کیوکوشین%' then 'کاراته کیوکوشین'
      when v_style ilike '%نینجوتسو%' then 'نینجوتسو'
      else null
    end;

    if v_course_name is null then
      raise exception 'سبک «%» در فهرست دوره‌های آکادمی قابل تطبیق نیست؛ تبدیل انجام نشد.', v_style;
    end if;

    select c.id
      into v_course_id
      from gym20.courses c
     where c.name = v_course_name
       and c.is_active = true
     limit 1;

    if v_course_id is null then
      raise exception 'دوره «%» در جدول دوره‌ها فعال نیست؛ تبدیل انجام نشد.', v_course_name;
    end if;

    insert into gym20.enrollments(
      student_id, course_id, package_type, total_sessions, start_date, status,
      class_type, age_group
    )
    values (
      v_student_id, v_course_id, 'sessions',
      v_request.total_sessions, current_date, 'active',
      coalesce(v_request.class_type, 'normal'),
      coalesce(v_request.age_group, 'adult')
    );

    v_count := v_count + 1;
  end loop;

  update gym20.public_registration_requests
     set status = 'converted',
         converted_student_id = v_student_id,
         converted_at = now(),
         converted_by = v_owner_id
   where id = p_request_id;

  return query select v_student_id, v_count;
end;
$function$

CREATE OR REPLACE FUNCTION gym20.create_student_public_link(p_student_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'gym20', 'auth'
AS $function$
declare
  v_code text;
begin
  if not exists (
    select 1 from gym20.profiles p
    where p.id = (select auth.uid())
      and p.role = 'owner'
      and p.is_active = true
  ) then
    raise exception 'دسترسی مدیر فعال نیست.';
  end if;

  if not exists (select 1 from gym20.students s where s.id = p_student_id) then
    raise exception 'هنرجو پیدا نشد.';
  end if;

  insert into gym20.student_public_links(student_id, code)
  values (p_student_id, substr(md5(gen_random_uuid()::text || clock_timestamp()::text), 1, 12))
  on conflict (student_id) do update
    set code = excluded.code, updated_at = now()
  returning code into v_code;

  return v_code;
end;
$function$

CREATE OR REPLACE FUNCTION gym20.create_student_term(p_student_id uuid, p_term_name text, p_start_date date, p_end_date date, p_total_sessions integer, p_duration_minutes integer, p_default_venue text, p_schedule_mode text, p_enrollment_ids uuid[])
 RETURNS TABLE(term_id uuid, draft_version_id uuid)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_term_id uuid;
  v_version_id uuid;
  v_count integer;
begin
  if (select auth.uid()) is null or not (select gym20.is_active_owner()) then
    raise exception 'اجازه انجام این عملیات را ندارید.' using errcode = '42501';
  end if;

  if p_student_id is null or not exists (
    select 1 from gym20.students s where s.id = p_student_id and s.is_active = true
  ) then
    raise exception 'هنرجوی فعال پیدا نشد.';
  end if;

  if p_term_name is null or char_length(btrim(p_term_name)) not between 1 and 100 then
    raise exception 'نام ترم معتبر نیست.';
  end if;

  if p_total_sessions is null or p_total_sessions < 1 or p_total_sessions > 100 then
    raise exception 'تعداد جلسات معتبر نیست.';
  end if;

  if p_duration_minutes not in (60,90) then
    raise exception 'مدت جلسه باید ۶۰ یا ۹۰ دقیقه باشد.';
  end if;

  if p_schedule_mode not in ('weekly','manual') then
    raise exception 'روش برنامه‌ریزی معتبر نیست.';
  end if;

  if p_end_date is not null and p_start_date is not null and p_end_date < p_start_date then
    raise exception 'تاریخ پایان ترم نمی‌تواند قبل از شروع باشد.';
  end if;

  if coalesce(cardinality(p_enrollment_ids),0) = 0 then
    raise exception 'حداقل یک سبک/ثبت‌نام را انتخاب کنید.';
  end if;

  select count(distinct x) into v_count from unnest(p_enrollment_ids) x;
  if v_count <> cardinality(p_enrollment_ids) then
    raise exception 'یک ثبت‌نام را بیش از یک بار انتخاب کرده‌اید.';
  end if;

  if exists (
    select 1
    from unnest(p_enrollment_ids) x
    left join gym20.enrollments e on e.id = x
    where e.id is null or e.student_id <> p_student_id or e.status not in ('active','paused')
  ) then
    raise exception 'یکی از سبک‌های انتخاب‌شده متعلق به این هنرجو نیست یا ثبت‌نام فعال ندارد.';
  end if;

  insert into gym20.student_terms(
    student_id, term_name, start_date, end_date, total_sessions,
    duration_minutes, default_venue, schedule_mode, created_by
  )
  values (
    p_student_id, btrim(p_term_name), p_start_date, p_end_date, p_total_sessions,
    p_duration_minutes, nullif(btrim(coalesce(p_default_venue,'')), ''),
    p_schedule_mode, (select auth.uid())
  )
  returning id into v_term_id;

  insert into gym20.term_enrollments(term_id, enrollment_id)
  select v_term_id, x from unnest(p_enrollment_ids) x;

  insert into gym20.term_schedule_versions(term_id, version_number, status, created_by)
  values (v_term_id, 1, 'draft', (select auth.uid()))
  returning id into v_version_id;

  return query select v_term_id, v_version_id;
end;
$function$

CREATE OR REPLACE FUNCTION gym20.create_term_draft_from_published(p_term_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_published_id uuid; v_draft_id uuid; v_next_version integer; v_old record; v_new_session_id uuid;
begin
  if (select auth.uid()) is null or not (select gym20.is_active_owner()) then
    raise exception 'اجازه انجام این عملیات را ندارید.' using errcode='42501';
  end if;
  perform 1 from gym20.student_terms where id=p_term_id for update;
  if not found then raise exception 'ترم پیدا نشد.'; end if;
  select id into v_draft_id from gym20.term_schedule_versions where term_id=p_term_id and status='draft' limit 1;
  if v_draft_id is not null then return v_draft_id; end if;
  select published_version_id into v_published_id from gym20.student_terms where id=p_term_id;
  select coalesce(max(version_number),0)+1 into v_next_version from gym20.term_schedule_versions where term_id=p_term_id;
  insert into gym20.term_schedule_versions(term_id,version_number,status,created_by)
  values(p_term_id,v_next_version,'draft',(select auth.uid())) returning id into v_draft_id;
  if v_published_id is not null then
    for v_old in select * from gym20.class_sessions where schedule_version_id=v_published_id order by session_number loop
      insert into gym20.class_sessions(course_id,enrollment_id,term_id,schedule_version_id,session_number,starts_at,ends_at,venue,notes,coach_name,status,created_by)
      values(v_old.course_id,v_old.enrollment_id,v_old.term_id,v_draft_id,v_old.session_number,v_old.starts_at,v_old.ends_at,v_old.venue,v_old.notes,v_old.coach_name,'scheduled',(select auth.uid()))
      returning id into v_new_session_id;
      insert into gym20.class_session_styles(session_id,enrollment_id)
      select v_new_session_id,css.enrollment_id from gym20.class_session_styles css where css.session_id=v_old.id
      on conflict do nothing;
      if not exists(select 1 from gym20.class_session_styles where session_id=v_new_session_id) and v_old.enrollment_id is not null then
        insert into gym20.class_session_styles(session_id,enrollment_id) values(v_new_session_id,v_old.enrollment_id);
      end if;
    end loop;
  end if;
  return v_draft_id;
end;
$function$

CREATE OR REPLACE FUNCTION gym20.publish_term_schedule(p_term_id uuid, p_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_total integer; v_status text; v_count integer;
begin
  if (select auth.uid()) is null or not (select gym20.is_active_owner()) then
    raise exception 'اجازه انجام این عملیات را ندارید.' using errcode='42501';
  end if;
  select t.total_sessions,v.status into v_total,v_status
  from gym20.student_terms t join gym20.term_schedule_versions v on v.term_id=t.id
  where t.id=p_term_id and v.id=p_version_id for update of t,v;
  if v_status is null or v_status<>'draft' then raise exception 'نسخه انتخاب‌شده پیش‌نویس قابل انتشار نیست.'; end if;
  select count(*) into v_count from gym20.class_sessions where schedule_version_id=p_version_id;
  if v_count<>v_total then raise exception 'تعداد جلسات برنامه باید دقیقاً برابر تعداد جلسات کل ترم باشد.'; end if;
  if exists (
    select 1 from gym20.class_sessions cs
    where cs.schedule_version_id=p_version_id
      and not exists(select 1 from gym20.class_session_styles css where css.session_id=cs.id)
  ) then raise exception 'برای هر جلسه حداقل یک سبک باید انتخاب شود.'; end if;
  if exists (
    select 1 from gym20.term_enrollments te
    where te.term_id=p_term_id and not exists (
      select 1 from gym20.class_sessions cs
      join gym20.class_session_styles css on css.session_id=cs.id
      where cs.schedule_version_id=p_version_id and css.enrollment_id=te.enrollment_id
    )
  ) then raise exception 'برای تمام سبک‌های انتخاب‌شده حداقل یک جلسه باید برنامه‌ریزی شود.'; end if;
  update gym20.term_schedule_versions set status='superseded'
   where term_id=p_term_id and status='published';
  update gym20.term_schedule_versions set status='published',published_at=now() where id=p_version_id;
  update gym20.student_terms set published_version_id=p_version_id,updated_at=now() where id=p_term_id;
end;
$function$

CREATE OR REPLACE FUNCTION gym20.replace_term_draft_sessions(p_version_id uuid, p_sessions jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_term_id uuid;
  v_total integer;
  v_duration integer;
  v_student_id uuid;
  v_inserted integer := 0;
  v_session_id uuid;
  v_session_rec record;
  v_course_id uuid;
  v_enrollment_id uuid;
begin
  if (select auth.uid()) is null or not (select gym20.is_active_owner()) then
    raise exception 'اجازه انجام این عملیات را ندارید.' using errcode = '42501';
  end if;
  if p_sessions is null or jsonb_typeof(p_sessions) <> 'array' then
    raise exception 'فهرست جلسات معتبر نیست.';
  end if;
  select t.id,t.total_sessions,t.duration_minutes,t.student_id
    into v_term_id,v_total,v_duration,v_student_id
  from gym20.term_schedule_versions v
  join gym20.student_terms t on t.id=v.term_id
  where v.id=p_version_id and v.status='draft'
  for update of v,t;
  if v_term_id is null then raise exception 'نسخه پیش‌نویس پیدا نشد یا قبلاً منتشر شده است.'; end if;
  if exists (
    select 1 from gym20.class_sessions cs join gym20.attendance a on a.session_id=cs.id
    where cs.schedule_version_id=p_version_id
  ) then raise exception 'برای این پیش‌نویس حضور و غیاب ثبت شده است؛ ویرایش مستقیم مجاز نیست.'; end if;
  if jsonb_array_length(p_sessions) <> v_total then
    raise exception 'تعداد جلسات باید دقیقاً برابر تعداد کل جلسات ترم باشد؛ تعداد سبک‌ها در این عدد ضرب نمی‌شود.';
  end if;
  if exists (
    select 1 from jsonb_to_recordset(p_sessions) as session_row(
      session_number integer, starts_at timestamptz, ends_at timestamptz,
      venue text, notes text, coach_name text, enrollment_ids uuid[]
    )
    where session_row.session_number is null or session_row.session_number < 1 or session_row.session_number > v_total
       or session_row.starts_at is null or session_row.ends_at is null or session_row.ends_at <= session_row.starts_at
       or extract(epoch from (session_row.ends_at-session_row.starts_at)) <> v_duration*60
       or char_length(coalesce(session_row.venue,''))>250 or char_length(coalesce(session_row.notes,''))>1000
       or coalesce(cardinality(session_row.enrollment_ids),0)=0
  ) then raise exception 'اطلاعات یکی از جلسات ناقص یا نامعتبر است؛ برای هر جلسه حداقل یک سبک انتخاب کنید.'; end if;
  if exists (
    select 1 from jsonb_to_recordset(p_sessions) as session_row(
      session_number integer, starts_at timestamptz, ends_at timestamptz,
      venue text, notes text, coach_name text, enrollment_ids uuid[]
    ) group by session_row.session_number having count(*)>1
  ) then raise exception 'شماره جلسه تکراری است.'; end if;
  if (select count(distinct session_row.session_number) from jsonb_to_recordset(p_sessions) as session_row(
      session_number integer, starts_at timestamptz, ends_at timestamptz,
      venue text, notes text, coach_name text, enrollment_ids uuid[]
    )) <> v_total then raise exception 'شماره جلسات باید از ۱ تا تعداد کل جلسات ترم کامل باشد.'; end if;
  if exists (
    select 1
    from jsonb_to_recordset(p_sessions) as session_row(
      session_number integer, starts_at timestamptz, ends_at timestamptz,
      venue text, notes text, coach_name text, enrollment_ids uuid[]
    )
    cross join lateral unnest(session_row.enrollment_ids) as ids(enrollment_id)
    left join gym20.term_enrollments te on te.term_id=v_term_id and te.enrollment_id=ids.enrollment_id
    where te.enrollment_id is null
  ) then raise exception 'یکی از سبک‌های جلسه جزو سبک‌های انتخاب‌شده این ترم نیست.'; end if;
  if exists (
    select 1 from jsonb_to_recordset(p_sessions) as session_row(
      session_number integer, starts_at timestamptz, ends_at timestamptz,
      venue text, notes text, coach_name text, enrollment_ids uuid[]
    ) cross join lateral unnest(session_row.enrollment_ids) as ids(enrollment_id)
    group by session_row.session_number,ids.enrollment_id having count(*)>1
  ) then raise exception 'یک سبک در یک جلسه دوبار انتخاب شده است.'; end if;
  if exists (
    select 1 from gym20.term_enrollments te
    where te.term_id=v_term_id and not exists (
      select 1 from jsonb_to_recordset(p_sessions) as session_row(
        session_number integer, starts_at timestamptz, ends_at timestamptz,
        venue text, notes text, coach_name text, enrollment_ids uuid[]
      ) cross join lateral unnest(session_row.enrollment_ids) as ids(enrollment_id)
      where ids.enrollment_id=te.enrollment_id
    )
  ) then raise exception 'برای همه سبک‌های انتخاب‌شده باید حداقل یک جلسه اختصاص داده شود.'; end if;

  delete from gym20.class_sessions where schedule_version_id=p_version_id;
  for v_session_rec in select * from jsonb_to_recordset(p_sessions) as session_row(
    session_number integer, starts_at timestamptz, ends_at timestamptz,
    venue text, notes text, coach_name text, enrollment_ids uuid[]
  ) order by session_number
  loop
    v_enrollment_id := v_session_rec.enrollment_ids[1];
    select e.course_id into v_course_id from gym20.enrollments e where e.id=v_enrollment_id;
    insert into gym20.class_sessions(
      course_id,enrollment_id,term_id,schedule_version_id,session_number,
      starts_at,ends_at,venue,notes,coach_name,status,created_by
    ) values (
      v_course_id,null,v_term_id,p_version_id,v_session_rec.session_number,
      v_session_rec.starts_at,v_session_rec.ends_at,nullif(btrim(coalesce(v_session_rec.venue,'')),''),
      nullif(btrim(coalesce(v_session_rec.notes,'')),''),nullif(btrim(coalesce(v_session_rec.coach_name,'')),''),'scheduled',(select auth.uid())
    ) returning id into v_session_id;
    insert into gym20.class_session_styles(session_id,enrollment_id)
    select v_session_id,ids.enrollment_id from unnest(v_session_rec.enrollment_ids) ids(enrollment_id);
    v_inserted:=v_inserted+1;
  end loop;
  return v_inserted;
end;
$function$

CREATE OR REPLACE FUNCTION gym20.set_student_exercise_completion(p_code text, p_exercise_id uuid, p_completed boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_student_id uuid; v_rows integer;
begin
  if p_code is null or p_code !~ '^[0-9a-f]{12}$' then return false; end if;
  select l.student_id into v_student_id from gym20.student_public_links l where l.code=p_code limit 1;
  if v_student_id is null then return false; end if;
  update gym20.student_exercises
  set is_completed=coalesce(p_completed,false),
      completed_at=case when coalesce(p_completed,false) then now() else null end
  where id=p_exercise_id and student_id=v_student_id;
  get diagnostics v_rows=row_count;
  return v_rows=1;
end;
$function$

CREATE OR REPLACE FUNCTION gym20.submit_public_registration(p_full_name text, p_phone text, p_birth_date date, p_notes text, p_selected_styles text[], p_age_group text, p_class_type text, p_total_sessions integer, p_payment_confirmed boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id uuid;
  v_styles text[];
begin
  if p_full_name is null or char_length(btrim(p_full_name)) < 2
     or char_length(btrim(p_full_name)) > 120 then
    raise exception 'نام و نام خانوادگی معتبر وارد کنید.';
  end if;

  if p_phone is null
     or char_length(regexp_replace(p_phone, '[^0-9+]', '', 'g')) < 8
     or char_length(regexp_replace(p_phone, '[^0-9+]', '', 'g')) > 16 then
    raise exception 'شماره تلفن معتبر وارد کنید.';
  end if;

  if p_notes is not null and char_length(p_notes) > 1000 then
    raise exception 'توضیحات بیش از حد طولانی است.';
  end if;

  if p_birth_date is not null and (p_birth_date > current_date or p_birth_date < date '1900-01-01') then
    raise exception 'تاریخ تولد معتبر نیست.';
  end if;

  if p_selected_styles is null
     or cardinality(p_selected_styles) < 1
     or cardinality(p_selected_styles) > 20 then
    raise exception 'حداقل یک سبک معتبر انتخاب کنید.';
  end if;

  if exists (
    select 1
    from unnest(p_selected_styles) as t(style_name)
    where style_name is null
       or char_length(btrim(style_name)) < 1
       or char_length(btrim(style_name)) > 80
  ) then
    raise exception 'نام یکی از سبک‌های انتخاب‌شده معتبر نیست.';
  end if;

  if p_age_group is null or p_age_group not in ('adult', 'kids') then
    raise exception 'رده سنی معتبر نیست.';
  end if;

  if p_class_type is null or p_class_type not in ('normal', 'semi', 'private', 'vip') then
    raise exception 'نوع کلاس معتبر نیست.';
  end if;

  if p_total_sessions is null or p_total_sessions not in (8, 10, 12) then
    raise exception 'تعداد جلسات معتبر نیست.';
  end if;

  if p_payment_confirmed is distinct from true then
    raise exception 'ابتدا پرداخت شهریه را تأیید کنید.';
  end if;

  select array_agg(btrim(style_name) order by ord)
    into v_styles
  from unnest(p_selected_styles) with ordinality as t(style_name, ord);

  insert into gym20.public_registration_requests
    (full_name, phone, birth_date, notes, course_id, selected_styles, age_group,
     class_type, total_sessions, package_type, payment_confirmed)
  values
    (btrim(p_full_name),
     regexp_replace(btrim(p_phone), '[[:space:]]+', '', 'g'),
     p_birth_date,
     nullif(btrim(coalesce(p_notes, '')), ''),
     null,
     v_styles,
     p_age_group,
     p_class_type,
     p_total_sessions,
     'sessions',
     true)
  returning id into v_id;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION gym20.update_registration_request_status(p_request_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is null or not (select gym20.is_active_owner()) then
    raise exception 'اجازه انجام این عملیات را ندارید.' using errcode = '42501';
  end if;

  if p_status not in ('pending','approved','rejected') then
    raise exception 'وضعیت انتخاب‌شده معتبر نیست.';
  end if;

  update gym20.public_registration_requests
     set status = p_status
   where id = p_request_id
     and converted_student_id is null
     and status <> 'converted';

  if not found then
    raise exception 'درخواست پیدا نشد یا قبلاً به هنرجو تبدیل شده است.';
  end if;
end;
$function$
